-- ==============================================================================
-- One vote per person per post.
-- Guests have no login, so a "person" is a per-browser voter id generated by the app;
-- a signed-in host votes as their auth user id (enforced server-side).
-- Votes can only be cast/removed through toggle_vote(), and votes_count is kept
-- in sync by a trigger (guests are not allowed to update posts directly).
-- ==============================================================================

-- 1. Who cast the vote
ALTER TABLE public.reactions ADD COLUMN IF NOT EXISTS voter_id text;

-- 2. At most one vote per voter per post
CREATE UNIQUE INDEX IF NOT EXISTS reactions_one_vote_per_voter
  ON public.reactions (post_id, voter_id)
  WHERE reaction_type = 'vote';

CREATE INDEX IF NOT EXISTS idx_reactions_event_voter
  ON public.reactions (event_id, voter_id)
  WHERE reaction_type = 'vote';

-- 3. Keep posts.votes_count equal to the number of vote rows
CREATE OR REPLACE FUNCTION public.sync_post_votes_count()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  target_post uuid;
  target_type text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    target_post := OLD.post_id;
    target_type := OLD.reaction_type;
  ELSE
    target_post := NEW.post_id;
    target_type := NEW.reaction_type;
  END IF;

  IF target_type = 'vote' AND target_post IS NOT NULL THEN
    UPDATE posts
    SET votes_count = (
      SELECT count(*) FROM reactions WHERE post_id = target_post AND reaction_type = 'vote'
    )
    WHERE id = target_post;
  END IF;
  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS reactions_sync_votes_count ON public.reactions;
CREATE TRIGGER reactions_sync_votes_count
  AFTER INSERT OR DELETE ON public.reactions
  FOR EACH ROW EXECUTE FUNCTION public.sync_post_votes_count();

-- 4. The only way to vote: toggles the caller's own vote and returns the new state
CREATE OR REPLACE FUNCTION public.toggle_vote(p_post_id uuid, p_voter_id text)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_voter text := COALESCE(auth.uid()::text, NULLIF(trim(p_voter_id), ''));
  v_event uuid;
  v_private boolean;
  v_removed int;
  v_count int;
BEGIN
  IF v_voter IS NULL OR length(v_voter) > 64 THEN
    RAISE EXCEPTION 'A voter id is required';
  END IF;

  SELECT event_id, is_private INTO v_event, v_private FROM posts WHERE id = p_post_id;
  IF NOT FOUND OR v_private THEN
    RAISE EXCEPTION 'Post not found';
  END IF;

  DELETE FROM reactions
  WHERE post_id = p_post_id AND voter_id = v_voter AND reaction_type = 'vote';
  GET DIAGNOSTICS v_removed = ROW_COUNT;

  IF v_removed = 0 THEN
    INSERT INTO reactions (post_id, event_id, voter_id, guest_id, reaction_type)
    VALUES (p_post_id, v_event, v_voter, auth.uid(), 'vote')
    ON CONFLICT DO NOTHING;
  END IF;

  SELECT votes_count INTO v_count FROM posts WHERE id = p_post_id;
  RETURN json_build_object('voted', v_removed = 0, 'votes', COALESCE(v_count, 0));
END;
$$;

-- 5. Which posts in an event the caller has voted for (to restore the filled hearts)
CREATE OR REPLACE FUNCTION public.my_voted_posts(p_event_id uuid, p_voter_id text)
RETURNS SETOF uuid
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT post_id
  FROM reactions
  WHERE event_id = p_event_id
    AND reaction_type = 'vote'
    AND voter_id = COALESCE(auth.uid()::text, NULLIF(trim(p_voter_id), ''));
$$;

GRANT EXECUTE ON FUNCTION public.toggle_vote(uuid, text) TO anon, authenticated;
GRANT EXECUTE ON FUNCTION public.my_voted_posts(uuid, text) TO anon, authenticated;

-- 6. Lock down direct access to reactions
--    - no public reads (voter ids stay private)
--    - no direct deletes (previously anyone could delete anyone's votes)
--    - direct inserts only for emoji reactions; votes must go through toggle_vote()
DROP POLICY IF EXISTS "Reactions viewable by everyone" ON public.reactions;
DROP POLICY IF EXISTS "Anyone can remove their reaction" ON public.reactions;
DROP POLICY IF EXISTS "Anyone can insert reactions" ON public.reactions;
DROP POLICY IF EXISTS "Anyone can insert emoji reactions" ON public.reactions;
CREATE POLICY "Anyone can insert emoji reactions"
  ON public.reactions FOR INSERT
  WITH CHECK (reaction_type <> 'vote');

-- 7. Make existing counts match the vote rows that actually exist
UPDATE public.posts p
SET votes_count = (
  SELECT count(*) FROM public.reactions r WHERE r.post_id = p.id AND r.reaction_type = 'vote'
)
WHERE p.votes_count IS DISTINCT FROM (
  SELECT count(*) FROM public.reactions r WHERE r.post_id = p.id AND r.reaction_type = 'vote'
);
